INSERT INTO `wp_addonlibrary_addons` (`id`, `title`, `name`, `alias`, `addontype`, `description`, `ordering`, `templates`, `config`, `catid`, `is_active`, `test_slot1`, `test_slot2`, `test_slot3`) VALUES
	(1, 'Caption Reveal Content Box', 'zoom_caption_reveal_content_box_elementor', 'zoom_caption_reveal_content_box', 'elementor', 'The Caption Reveal Content Box Widget for Elementor is a nice content box that shows information on your website, revealing the caption with a zoom effect when you hover over it.', 1, '{"html":"<div id=\\"{{uc_id}}\\" class=\\"zoom_caption_reveal_content_box\\" role=\\"region\\" aria-labelledby=\\"{{caption|ucsafe|raw}}\\">\\n  <div class=\\"image-caption-reveal-on-hover\\">\\n  <\\/div>\\n\\n    <div class=\\"icroh-caption\\">\\n      {% if show_title == \\"true\\" %}<{{title_tag}} class=\\"icroh-title\\">{{title|raw}}<\\/{{title_tag}}>{% endif %}\\n      <div class=\\"icroh-text\\" aria-hidden=\\"true\\" >{{caption|raw}}<\\/div>\\n    <\\/div>\\n  \\n  {% if enable_link == \\"true\\" %}\\n\\t  <a href=\\"{{link}}\\" class=\\"ue-link\\" {{link_html_attributes|raw}} aria-label=\\"{{caption|ucsafe|raw}}\\" tabindex=\\"0\\"><\\/a> \\n  {% endif %}\\t\\n  \\n  {% if show_badge == \\"true\\" %}\\n    <div class=\\"ue-badge-wrapper\\">\\n      <div class=\\"ue-badge\\">\\n        {% if show_badge_icon == \\"true\\" %}<span class=\\"ue-badge-icon\\">{{badge_icon_html|ucsafe|raw}}<\\/span>{% endif %}\\n        {{badge_text|raw}}\\n      <\\/div> \\n    <\\/div>\\n  {% endif %}\\n\\n<\\/div>","css":"#{{uc_id}} *{\\n  box-sizing:border-box;\\n}\\n#{{uc_id}}{\\n  position:relative;\\n  overflow:hidden;\\n  direction:{{rtl}}!important;\\n}\\n\\n#{{uc_id}} .ue-link{\\n  display:block;\\n  position:absolute;\\n  left:0;\\n  right:0;\\n  bottom:0;\\n  top:0;\\n}\\n\\n#{{uc_id}} .image-caption-reveal-on-hover{\\n  transition:{{transition_duration}}ms;\\n  width:100%;\\n  background-color:lightgray;\\n  background-image:url({{image}});\\n  background-size:cover;\\n  position:absolute;\\n  top:0;\\n  left:0;\\n  bottom:0;\\n  right:0;\\n  transform:scale(100%,100%);\\n}\\n\\n#{{uc_id}} .icroh-caption{\\n  transition:{{transition_duration}}ms;\\n  position:absolute;\\n  color:white;\\n  width:100%;\\n}\\n\\n#{{uc_id}} .icroh-text{\\n  display:none;\\n}\\n#{{uc_id}}.ue_crcb_active .icroh-text{\\n  display:block;\\n}\\n{% if show_content_on_breakpoint == \\"true\\" %}\\n  @media only screen and (max-width: {{breakpoint}}px) {\\n    #{{uc_id}} .icroh-text{\\n      display:block!important;\\n    }\\n  }\\n{% endif %}\\n\\n{% if show_badge == \\"true\\" %}\\n  #{{uc_id}} .ue-badge-wrapper{\\n    {% if badge_placement == \\"left\\" %}\\n      transform: rotate(0deg);\\n      right:unset;\\n      left:0;\\n    {% elseif badge_placement == \\"right\\" %}\\n      transform: rotate(90deg);\\n      right:0;\\n      left:unset;\\n    {% endif %}\\n    position:absolute;\\n    top:0;\\n    z-index: 3;\\n    overflow:hidden;\\n  }\\n  #{{uc_id}} .ue-badge{\\n    width: 150%;\\n    display:inline-flex;\\n    justify-content:center;\\n    align-items:center;\\n  }\\n  #{{uc_id}} .ue-badge-icon{\\n    display:inline-flex;\\n    justify-content:center;\\n    align-items:center;\\n  }\\n  .ue_badge\\n  {\\n    font-size:10px;\\n    line-height:1em;\\n  }\\n{% endif %}\\n\\n{% if show_title == \\"true\\" %}\\n.icroh-title{\\n  font-size:18px;\\n}\\n{% endif %}","js":"{{ ucfunc(\\"put_docready_start\\") }}\\n  \\n   var objWidget = jQuery(\\"#{{uc_id}}\\");\\n  \\n   var ueCaption = objWidget.find(\\".icroh-text\\");\\n   var showOnBreakpoint = {{show_content_on_breakpoint}};\\n\\n   function initCaptionRevealContentBox() {  \\n     \\n     objWidget.off(\\"mouseenter mouseleave\\");\\n     ueCaption.css({height: \\"\\"});\\n     \\n     if (showOnBreakpoint && window.innerWidth <= {{breakpoint}}) {\\n       objWidget.addClass(\\"ue_crcb_active\\");\\n     } else {\\n       \\n       objWidget.on(\\"mouseenter\\", function() {\\n           ueCaption.stop(true, false).slideDown({{transition_duration}});\\n           objWidget.addClass(\\"ue_crcb_active\\");\\n       });\\n       objWidget.on(\\"mouseleave\\", function() {\\n           ueCaption.stop(true, false).slideUp({{transition_duration}});\\n           objWidget.removeClass(\\"ue_crcb_active\\");\\n       });\\n       \\n     }\\n   }\\n\\n  \\/\\/ Initial run\\n  initCaptionRevealContentBox();\\n\\n  \\/\\/ Rerun on resize\\n  jQuery(window).on(\\"resize\\", function() {\\n    initCaptionRevealContentBox();\\n  });\\n    \\t\\n{{ ucfunc(\\"put_docready_end\\") }}"}', '{"options":{"enable_items":"","path_assets":"zoom_caption_reveal_content_box","js_as_module":false,"addon_icon":"","dynamic_addon":"false","dynamic_post_enable_customfields":"false","dynamic_post_enable_category":"false","description":"The Caption Reveal Content Box Widget for Elementor is a nice content box that shows information on your website, revealing the caption with a zoom effect when you hover over it.","link_resource":"","link_preview":"https:\\/\\/unlimited-elements.com\\/caption-reveal-content-box-widget-for-elementor","show_small_icon":"true","preview_size":"column","preview_custom_width":"","preview_bgcol":"#ffffff","special":"","special_data":"","is_free_addon":true,"is_new_addon":false,"is_trending":false},"params":[{"type":"uc_slider","title":"Height","name":"height","description":"","enable_condition":false,"condition_attribute":"","condition_operator":"equal","condition_value":[],"condition_attribute2":"","condition_operator2":"equal","condition_value2":null,"label_block":false,"tabname":"","default_value":"300","min":"100","max":"600","step":"10","units":"px","is_responsive":true,"default_value_tablet":"","default_value_mobile":"","selector":".zoom_caption_reveal_content_box","selector_value":"height: {{SIZE}}{{UNIT}};","show_more_selectors":false,"selector2":"","selector2_value":"width: {{SIZE}}{{UNIT}};","selector3":"","selector3_value":"width: {{SIZE}}{{UNIT}};","__attr_catid__":"cat_style_ax1y4qw4"},{"type":"uc_image","title":"Image","name":"image","description":"","enable_condition":false,"condition_attribute":"","condition_operator":"equal","condition_va