	(2, 'Card Carousel', 'card_carousel_elementor', 'card_carousel', 'elementor', 'The Card Carousel widget displays multiple pieces of content in a carousel format, allowing for smooth transitions between items and adding an interactive touch to your Elementor website.', 1, '{"html":"<div class=\\"uc_classic_carousel\\" id=\\"{{uc_id}}-wrapper\\">\\n  <div class=\\"uc_carousel owl-carousel uc-items-wrapper {{remote_parent.class}} {{uc_filtering_addclass}}\\" id=\\"{{uc_id}}\\" {{remote_parent.attributes|raw}} {{uc_filtering_attributes|raw}}>\\n    {{put_items()}}\\n  <\\/div>\\n<\\/div>","html_item":"{# twig vars #}{##}\\n{% set titleElem %}<{{title_html_tag}}  class=\\"card_carousel_title\\">{{item.title|raw}}<\\/{{title_html_tag}}>{% endset %}\\n\\n{% set linkTitleElem %}\\n  {% if title_link == \\"true\\" %}\\n  <a href=\\"{{item.link|raw}}\\" {{item.link_html_attributes|raw}}>{{titleElem}}<\\/a>\\n  {% else %}\\n  {{titleElem}}\\n  {% endif %}\\n{% endset %}{# end linkTitleElem #}{##}\\n\\n{% set buttonText %}{% if item.btn_text|raw is empty %}{{button_text|raw}}{% else %}{{item.btn_text|raw}}{% endif %}{% endset %}\\n{# end twig vars #}{##}\\n\\n<div id=\\"{{item.item_id}}\\" class=\\"uc_classic_carousel_container_holder ue-item {{item.item_repeater_class}}\\" data-hide-item=\\"{{item.hide_item}}\\">  \\n  <div class=\\"ue-carousel-item\\">\\n    \\n    {% if show_top_decoration == \\"true\\" %}<span class=\\"uc_classic_carousel_border\\" style=\\"\\"><\\/span>{% endif %}\\n    \\n    {% if show_title == \\"above_image\\" %}{{linkTitleElem}}{% endif %}\\n\\n    {% if show_image == \\"true\\" %}\\n      <div class=\\"uc_classic_carousel_placeholder\\">\\n        {% if image_link == \\"true\\" %}<a href=\\"{{item.link|raw}}\\" title=\\"{{item.btn_text}}\\" {{item.link_html_attributes|raw}}>{% endif %}\\n          <img src=\\"{{item.image}}\\" {{item.image_attributes|raw}}>\\n        {% if image_link == \\"true\\" %}<\\/a>{% endif %}\\n        {% if enable_img_overlay == \\"true\\" %}<div class=\\"ue_card_carousel_image_overlay\\"><\\/div>{% endif %}\\n      <\\/div>\\n    {% endif %}\\n\\n    <div class=\\"uc_classic_carousel_content\\" style=\\"direction:{{direction}};\\">    \\n\\n      {% if show_icon == \\"true\\" %}\\n        <div class=\\"ue-item-icon-wrapper\\">\\n           <div class=\\"ue-item-icon\\">{{item.icon_html|raw}}<\\/div>\\n        <\\/div>\\n      {% endif %}\\n\\n      {% if show_title == \\"above_content\\" %}{{linkTitleElem}}{% endif %}\\n      {% if show_text == \\"true\\" %}<div class=\\"card_carousel_text\\">{{item.content|raw}}<\\/div>{% endif %}\\n      {% if show_title == \\"under_content\\" %}{{linkTitleElem}}{% endif %}\\t\\n\\n      {% if show_button == \\"true\\" %}\\n        <div class=\\"ue_button\\">\\n          <a class=\\"uc_more_btn {{button_hover_animation}}\\" href=\\"{{item.link|raw}}\\" title=\\"{{item.btn_text}}\\" {{item.link_html_attributes|raw}}>{{buttonText}}<\\/a>\\n      \\t<\\/div>   \\n      {% endif %}\\t\\n      \\n    <\\/div>\\n    \\n  <\\/div>\\n<\\/div>","css":"#{{uc_id}}-wrapper{\\n  min-height:1px;\\n}\\n\\n#{{uc_id}} *{\\n\\t-webkit-box-sizing: border-box;\\n\\t-moz-box-sizing: border-box;\\n\\tbox-sizing: border-box;\\n}\\n\\n#{{uc_id}} .ue-carousel-item{\\n  overflow:hidden;\\n  transition:0.3s;\\n}\\n\\n#{{uc_id}} .uc_classic_carousel_container_holder{\\n\\tdisplay:block;\\n\\tposition:relative;\\n\\twidth:100%;\\n    box-sizing: border-box;\\n}\\n#{{uc_id}} .uc_classic_carousel_placeholder{\\n   position:relative;\\n}\\n\\n{% if enable_img_overlay == \\"true\\" %}\\n#{{uc_id}} .ue_card_carousel_image_overlay{\\n  position:absolute;\\n  top:0;\\n  bottom:0;\\n  left:0;\\n  right:0;\\n  transition:0.3s;\\n}\\n{% endif %}\\n\\n#{{uc_id}} .uc_classic_carousel_placeholder img, #{{uc_id}} .ue_card_carousel_image_overlay{\\n  transition: all 300ms;\\n}\\n\\n.card_carousel_title{\\n\\tfont-size:21px;\\n}\\n\\n.uc_classic_carousel .uc_classic_carousel_border{\\n\\tdisplay:block;\\n    margin:0 auto;\\n}\\n\\n.uc_classic_carousel  .uc_classic_carousel_placeholder img{\\n\\twidth:100%;    \\n    display:block;\\n}\\n\\n.uc_classic_carousel .uc_classic_carousel_content{\\n  display: flex;\\n  flex-flow: column nowrap;\\n}\\n\\n.uc_classic_carousel .ue_button{\\n  margin-top:auto;\\n}\\n\\n.uc_classic_carousel .uc_classic_carousel_content .uc_more_btn {\\n\\tdisplay:inline-block;\\n\\ttext-decoration:none;\\n\\ttransition: all 0.5s ease;\\n}\\n\\n#{{uc_id}} .owl-dots {\\n  overflow:hidden;\\n  text-align:{{dot_alignment}};\\n}\\n\\n#{{uc_id}} .owl-dot {\\n  border-radius:50%;\\n  display:inline-block;\\n}\\n\\n#{{uc_id}} .owl-nav .owl-prev,\\n#{{uc_id}} .owl-nav .owl-next{\\n    position:absolute;\\n    display:flex;\\n  \\tjustify-content: center;\\n  \\talign-items: center;\\n    text-align:center;\\n}\\n\\n#{{uc_id}} .owl-nav .disabled{\\n    display: none;  \\n}\\n\\n\\n#{{uc_id}} .ue-item-icon{\\n  line-height:1em;\\n  display:inline-flex;\\n  justify-content:center;\\n  align-items:center;  \\n}\\n\\n#{{uc_id}} .ue-item-icon svg{\\n  height:1em;\\n  width:1em;\\n}\\n\\n#{{uc_id}} .ue-item-icon-wrapper{\\n  display:flex;\\n}\\n\\n#{{uc_id}} .uc_classic_carousel_container_holder {\\n\\t max-width: {{item_width}};\\n}\\n\\n{% if transition_easing == \\"false\\" %}\\n  #{{uc_id}} .owl-stage        {\\n    transition-timing-function: linear!important;\\n  }\\n{% endif %}\\n\\n{% if carousel_animation != \\"none\\" %}\\n  #{{uc_id}} .owl-item{\\n    animation-duration: {{transition_speed}}ms;\\n  }\\n{% endif %}\\n\\n@media screen and (max-width: 1024px) {\\n  #{{uc_id}} .uc_classic_carousel_container_holder {\\n\\t max-width: {{item_width_tablet}};\\n  }\\n}\\n\\n@media screen and (max-width: 767px) {\\n  #{{uc_id}} .uc_classic_carousel_container_holder {\\n    max-width: {{item_width_mobile}};\\n  }\\n}","js":"{{ ucfunc(\\"put_docready_start\\") }}\\n      \\n    var objCarousel = jQuery(\'#{{uc_id}}\');\\n    \\n    function hideIndividualItems(){    \\t\\n      var objItems = objCarousel.find(\\".uc_classic_carousel_container_holder\\");\\n      \\n      if(!objItems)\\n        return(false);\\n      \\n      objItems.each(function(){      \\n      \\tvar objItem = jQuery(this);\\n        var dataHide = objItem.data(\\"hide-item\\");\\n        \\n        if(dataHide == true)          \\n        objItem.remove();      \\n      });    \\n    }\\n    \\n    function initCarousel(){        \\n      \\/\\/hide individual items if needed \\n      hideIndividualItems(); \\n    \\n      objCarousel.owlCarousel({\\n                loop: {{loop}},\\n                rtl:{{rtl}},\\n                autoplay:{{autoplay}},\\n                paddingType: \\"{{stage_padding_type}}\\",    \\n                autoplayHoverPause:{{autoplayhoverpause}},\\n                navText : [`<i class=\'{{left_arrow}}\'><\\/i>`,`<i class=\'{{right_arrow}}\'><\\/i>`],\\n                nav: {{show_arrows}},\\n                rewindNav : false,\\n                center:{{center}},\\n                mouseDrag:{{mouse_drag}},\\n                touchDrag:{{touch_drag}},                    \\n                setActiveClassOnMobile:{{active_on_mobile}},\\n                changeItemOnClick:{{scroll_on_click}},                 \\n                dots:{{show_bullets}},\\n                shuffle:{{shuffle}},\\n                scrollToHead:{{scroll_to_head}},\\n                scrollToHeadOffset: {{scroll_to_head_offset}},\\n                autoWidth: {{auto_width}},\\n                mousewheelControl: {{enable_mouse_wheel_control}},\\n                \\n                {% if carousel_animation == \\"fadeIn\\" %}\\n                animateIn: \\"{{carousel_animation}}\\",                    \\n                animateOut: \\"fadeOut\\",    \\t\\t \\n                {% endif %}\\n  \\n                {% if carousel_animation == \\"fadeInLeft\\" %}\\n                animateIn: \\"{{carousel_animation}}\\",                    \\n                animateOut: \\"fadeOutRight\\",    \\t\\t \\n                {% endif %}\\n  \\n                {% if carousel_animation == \\"fadeInRight\\" %}\\n                animateIn: \\"{{carousel_animation}}\\",                    \\n                animateOut: \\"fadeOutLeft\\",    \\t\\t \\n                {% endif %}\\t\\n  \\n                {% if carousel_animation == \\"fadeInUp\\" %}\\n                animateIn: \\"{{carousel_animation}}\\",                    \\n                animateOut: \\"fadeOutUp\\",    \\t\\t \\n                {% endif %}\\n  \\n                {% if carousel_animation == \\"fadeInDown\\" %}\\n                animateIn: \\"{{carousel_animation}}\\",                    \\n                animateOut: \\"fadeOutDown\\",    \\t\\t \\n                {% endif %}   \\n  \\n                {% if carousel_animation == \\"slideInLeft\\" %}\\n                animateIn: \\"{{carousel_animation}}\\",                    \\n                animateOut: \\"slideOutRight\\",    \\t\\t \\n                {% endif %}\\n  \\n                {% if carousel_animation == \\"slideInRight\\" %}\\n                animateIn: \\"{{carousel_animation}}\\",                    \\n                animateOut: \\"slideOutLeft\\",    \\t\\t \\n                {% endif %}\\n  \\n                {% if carousel_animation == \\"slideInUp\\" %}\\n                animateIn: \\"{{carousel_animation}}\\",                    \\n                animateOut: \\"slideOutUp\\",    \\t\\t \\n                {% endif %}\\t  \\n  \\n                {% if carousel_animation == \\"slideInDown\\" %}\\n                animateIn: \\"{{carousel_animation}}\\",                    \\n                animateOut: \\"slideOutDown\\",    \\t\\t \\n                {% endif %}\\t               \\n                              \\n                responsive: {\\n  \\n                       0 : {\\n                            items:{{number_of_items_mobile}},\\n                            slideBy: {{slides_to_scroll_mobile}},\\n                            scrollToHeadForceOnMobile: {{scroll_to_head_forced_on_mobile}},        \\n                            margin:{{margin_between_slides_mobile}},\\n                            autoplayTimeout:{{autoplay_interval_mobile}},\\n                            smartSpeed: {{transition_speed_mobile}},\\n                            {% if center == \\"false\\" %}\\n                                dotsEach: {{show_dots_each_x_item_mobile}},\\n                            {% endif %}\\t\\n  \\n                            {% if stage_padding_type != \\"none\\" %}\\n                                 stagePadding: {{stage_padding_mobile}},\\n                            {% endif %}\\t        \\n                        },\\n                        768 : {\\n                            items:{{number_of_items_tablet}},\\n                            slideBy: {{slides_to_scroll_tablet}},\\n                            margin:{{margin_between_slides_tablet}},\\n                            autoplayTimeout:{{autoplay_interval_tablet}},\\n                            smartSpeed: {{transition_speed_tablet}}, \\n                            {% if center == \\"false\\" %}\\n                                dotsEach: {{show_dots_each_x_item_tablet}},\\n                            {% endif %}\\t\\n  \\n                            {% if stage_padding_type != \\"none\\" %}\\n                                 stagePadding: {{stage_padding_tablet}},\\n                            {% endif %}\\t        \\n                        },\\n                        980 : {\\n                            items:{{number_of_items}},\\n                            slideBy: {{slides_to_scroll}},\\n                            margin:{{margin_between_slides}},\\n                            autoplayTimeout:{{autoplay_interval}},\\n                            smartSpeed: {{transition_speed}}, \\n                            {% if center == \\"false\\" %} \\n                   