	(25132, '_transient_dash_v2_88ae138922fe95674369b1cb3d215a2b', '<div class="rss-widget"><ul><li><a class=\'rsswidget\' href=\'https://wordpress.org/news/2026/09/wordpress-7-1-2-release/\'>WordPress 7.1.2 Release</a></li><li><a class=\'rsswidget\' href=\'https://wordpress.org/news/2026/09/owa-president/\'>WordPress Takes Its Turn Leading the Open Website Alliance</a></li></ul></div><div class="rss-widget"><ul><li><a class=\'rsswidget\' href=\'https://gutenbergtimes.com/gutenberg-24-0-the-road-to-7-2-a-new-default-theme-named-ipsum-and-more-weekend-edition-377/\'>Gutenberg Times: Gutenberg 24.0, the road to 7.2, a new default theme named Ipsum, and more—Weekend Edition 377</a></li><li><a class=\'rsswidget\' href=\'https://fluffyandflakey.blog/2026/09/25/enter-the-mess-shortcodes/\'>Dennis Snell: Enter the mess: Shortcodes</a></li><li><a class=\'rsswidget\' href=\'https://openchannels.fm/your-website-could-use-a-changelog-to-fuel-creativity/\'>Open Channels FM: Your Website Could Use a Changelog to Fuel Creativity</a></li></ul></div>', 'off'),
