INSERT INTO `wp_wfissues` (`id`, `time`, `lastUpdated`, `status`, `type`, `severity`, `ignoreP`, `ignoreC`, `shortMsg`, `longMsg`, `data`) VALUES
	(935, 1770121752, 1770121752, 'new', 'skippedPaths', 25, '6fd0d290b978eab8027e6b79501ac149', '6fd0d290b978eab8027e6b79501ac149', '1 path was skipped for the malware scan due to scan settings', 'The option "Scan files outside your WordPress installation" is off by default, which means 1 path and its file(s) will not be scanned for malware or unauthorized changes. To continue skipping this path, you may ignore this issue. Or to start scanning it, enable the option and subsequent scans will include it. Some paths may not be necessary to scan, so this is optional. <a href="https://www.wordfence.com/help/?query=scan-result-skipped-paths" target="_blank" rel="noopener noreferrer">Learn More<span class="screen-reader-text"> (opens in new tab)</span></a><br><br>The path skipped is C:\\laragon\\www\\gimnasio/.tmb', 'a:0:{}'),
	(936, 1770121764, 1770121764, 'new', 'knownfile', 25, '9bf5f19ed93b9877ea72c09417a343e1', '188f13de5deeb7a8bf005a7213a358d5', 'Old WordPress core file not removed during update: wp-includes/SimplePie/src/Core.php', 'This file is in a WordPress core location but is from an older version of WordPress and not used with your current version. Hosting or permissions issues can cause these files to get left behind when WordPress is updated and they should be removed if possible.', 'a:6:{s:4:"file";s:34:"wp-includes/SimplePie/src/Core.php";s:8:"realFile";s:58:"C:\\laragon\\www\\gimnasio/wp-includes/SimplePie/src/Core.php";s:5:"cType";s:4:"core";s:7:"canDiff";b:0;s:6:"canFix";b:0;s:9:"canDelete";b:1;}'),
	(947, 1770236005, 1770236005, 'new', 'wfPluginUpgrade', 50, '38277ea900c9df35d5fd6096d151cf90', '38277ea900c9df35d5fd6096d151cf90', 'The Plugin "All-in-One WP Migration and Backup" needs an upgrade (7.101 -> 7.102).', 'You need to upgrade "All-in-One WP Migration and Backup" to the newest version to ensure you have any security fixes the developer has released.', 'a:21:{s:4:"Name";s:34:"All-in-One WP Migration and Backup";s:9:"PluginURI";s:21:"https://servmask.com/";s:7:"Version";s:5:"7.101";s:11:"Description";s:154:"All-in-One WP Migration makes moving your entire WordPress site simple. Export or import your database, media, plugins, and themes with just a few clicks.";s:6:"Author";s:8:"ServMask";s:9:"AuthorURI";s:21:"https://servmask.com/";s:10:"TextDomain";s:23:"all-in-one-wp-migration";s:10:"DomainPath";s:10:"/languages";s:7:"Network";b:1;s:10:"RequiresWP";s:0:"";s:11:"RequiresPHP";s:0:"";s:9:"UpdateURI";s:0:"";s:15:"RequiresPlugins";s:0:"";s:5:"Title";s:34:"All-in-One WP Migration and Backup";s:10:"AuthorName";s:8:"ServMask";s:10:"pluginFile";s:94:"C:\\laragon\\www\\gimnasio/wp-content/plugins/all-in-one-wp-migration/all-in-one-wp-migration.php";s:4:"slug";s:23:"all-in-one-wp-migration";s:10:"newVersion";s:5:"7.102";s:5:"wpURL";s:53:"https://wordpress.org/plugins/all-in-one-wp-migration";s:15:"updateAvailable";b:1;s:10:"vulnerable";b:0;}'),
	(948, 1770236005, 1770236005, 'new', 'wfPluginUpgrade', 50, '168d33c6fbf3453c6e2ff26117b4b1dd', '168d33c6fbf3453c6e2ff26117b4b1dd', 'The Plugin "Elementor" needs an upgrade (3.33.4 -> 3.35.0).', 'You need to upgrade "Elementor" to the newest version to ensure you have any security fixes the developer has released.', 'a:21:{s:4:"Name";s:9:"Elementor";s:9:"PluginURI";s:87:"https://elementor.com/?utm_source=wp-plugins&utm_campaign=plugin-uri&utm_medium=wp-dash";s:7:"Version";s:6:"3.33.4";s:11:"Description";s:145:"The Elementor Website Builder has it all: drag and drop page builder, pixel perfect design, mobile responsive editing, and more. Get started now!";s:6:"Author";s:13:"Elementor.com";s:9:"AuthorURI";s:87:"https://elementor.com/?utm_source=wp-plugins&utm_campaign=author-uri&utm_medium=wp-dash";s:10:"TextDomain";s:9:"elementor";s:10:"DomainPath";s:0:"";s:7:"Network";b:0;s:10:"RequiresWP";s:3:"6.6";s:11:"RequiresPHP";s:3:"7.4";s:9:"UpdateURI";s:0:"";s:15:"RequiresPlugins";s:0:"";s:5:"Title";s:9:"Elementor";s:10:"AuthorName";s:13:"Elementor.com";s:10:"pluginFile";s:66:"C:\\laragon\\www\\gimnasio/wp-content/plugins/elementor/elementor.php";s:4:"slug";s:9:"elementor";s:10:"newVersion";s:6:"3.35.0";s:5:"wpURL";s:39:"https://wordpress.org/plugins/elementor";s:15:"updateAvailable";b:1;s:10:"vulnerable";b:0;}'),
